query:
mutation CreateOneFieldMetadataItem($input: CreateOneFieldMetadataInput!) {
  createOneField(input: $input) {
    id
    type
    name
    label
    description
    icon
    isActive
    isUnique
    isSearchable
    isNullable
    createdAt
    updatedAt
    settings
    defaultValue
    options
    isLabelSyncedWithName
    applicationId
    object {
      id
      __typename
    }
    relation {
      type
      sourceObjectMetadata {
        id
        nameSingular
        namePlural
        __typename
      }
      targetObjectMetadata {
        id
        nameSingular
        namePlural
        __typename
      }
      sourceFieldMetadata {
        id
        name
        __typename
      }
      targetFieldMetadata {
        id
        name
        __typename
      }
      __typename
    }
    morphRelations {
      type
      sourceObjectMetadata {
        id
        nameSingular
        namePlural
        __typename
      }
      targetObjectMetadata {
        id
        nameSingular
        namePlural
        __typename
      }
      sourceFieldMetadata {
        id
        name
        __typename
      }
      targetFieldMetadata {
        id
        name
        __typename
      }
      __typename
    }
    __typename
  }
}
